    static let batchBJ: [CaseTemplate] = [oldMillRoadBack, parkingLotShootingBack, rentalFireBack, borrowedTruckBack, parkingKnifeIntentBack, copperWireStrippingBack, restaurantFireClaimBack, tellerDrawerBack, gunUnderSeatBack, affairExtortionBack, breakRoomCoffeeBack, restaurantFireBack, kennelShootingBack, bloodTestStartupBack, knifeFightBack, coastalBodiesBack, joggerChaseBack, hotCarDeathBack, swattingCallBack, neighborhoodWatchBack, ptaTreasurerBack, staircaseDeathBack, lowcountryLawyerBack, churchArsonistBack, noteBanditBack, wrongWayDriverBack, catfishMeetupBack, deerCampFelonBack]

    static let oldMillRoadBack = SmallCases.make(
        key: "story.followup.oldMillRoadBack",
        category: .traffic,
        headlines: ["Driver Clocked at 80 Through Highway Work Zone", "Driver From Old Mill Road Case Charged With Reckless Driving"],
        law: "recklessDriving",
        spec: "Drove a motor vehicle on a highway carelessly and heedlessly in willful disregard of the safety of others, through a marked work zone, on {DATE}.",
        ages: 24...48,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was clocked at 80 mph through a marked highway work zone, weaving between cones past a road crew. A trooper's radar and dash camera recorded it. {DL} says traffic was backed up and the speed sign was hidden by a truck.",
        state: [E(.video, 3, "Trooper Dash Camera", "{D}'s car weaves past cones at high speed beside workers."), E(.document, 2, "Radar Log", "Radar reads 80 in a 45 work zone.")],
        defense: [E(.physical, 1, "Hidden Speed Sign", "A photo of a work truck blocking the reduced-speed sign.")],
        role: "State trooper",
        exam: [.direct("What is your assignment?", "\"I'm a state trooper who patrols the highways, with a focus on work zones and speeding.\""), .direct("What did you see?", "\"A car driving through a marked work zone at very high speed, weaving between cones next to a road crew.\""), .direct("What did your radar show?", "\"Eighty miles an hour, in a work zone with a posted limit of forty-five.\""), .direct("What does your dash camera show?", "\"{DL}'s car passing a line of slower cars, swerving between cones, and passing within feet of workers.\""), .direct("What was the danger?", "\"The workers were on foot beside the lane, and a car at that speed could have killed one of them.\""), .direct("What did {DL} say?", "\"{D.He} said traffic was backed up and that the reduced-speed sign was hidden by a work truck.\""), .cross("The sign was blocked?", "\"A work truck was partly blocking one sign, but there were other signs earlier.\""), .cross("Traffic was heavy?", "\"It was heavy at first, but it cleared before {DL} passed.\""), .cross("{DL} stopped when you turned on lights?", "\"Yes, {D.he} stopped quickly when I turned on my lights, and {D.he} was polite.\""), .cross("No one was hit?", "\"No one was hit, but a worker had to jump back into the cones.\""), .cross("The photo of the hidden sign is real?", "\"It is, but it shows only one of several signs.\"")],
        theory: ("{D} sped through a work zone past workers.", "A driver who could not see the reduced-speed sign."),
        allocution: "\"I did not look at the speedometer. I was in a hurry, and I didn't notice the work zone until I was past it. I know I was in this court before, and I should have learned. I'm sorry to the road crew, and I will slow down.\"",
        truths: ("{DL} had a prior case in this court and passed three other signs warning of the work zone.", "The truck did block the first sign, and traffic ahead had just opened up, making a speed increase easy to miss."),
        defendant: [.direct("Were you speeding through the work zone?", "\"I was going faster than I should have, but I didn't see the reduced-speed sign. A truck blocked it.\""), .direct("What do you remember?", "\"Traffic was backed up, and then it opened up. I sped up to make up time.\""), .direct("Did you see the workers?", "\"Not until I was close. I swerved around the cones, and I saw a worker step back.\""), .direct("Did you know about the work zone?", "\"I saw the first sign, but I thought it ended. I didn't see the others.\""), .direct("What did you do when the trooper stopped you?", "\"I pulled over right away and apologized. I told {TROOPER.him} I'd missed the sign.\""), .direct("What would you tell the road crew?", "\"I'm sorry for scaring you. I could have hurt you, and I'll slow down.\""), .cross("You have been cited for speeding in a work zone before, haven't you?", "\"Yes, and I told the court I'd be careful. I wasn't.\""), .cross("Eighty in a forty-five is nearly double the limit?", "\"It is nearly double the limit, and I know it was reckless.\""), .cross("The first sign was visible to you?", "\"It was visible to me, and I should have slowed down at once.\""), .cross("You'll take a driving class?", "\"Yes, I'll take a driving class, and I'll accept any suspension the court sets.\""), .cross("You'll slow down in work zones?", "\"Yes, from now on I'll slow down in every work zone, whatever the traffic.\"")],
        openings: ("A state trooper who patrols the highways with a focus on work zones saw a car drive through a marked work zone at very high speed, weaving between cones next to a road crew, and {D} was clocked at 80 mph, and the radar and dash camera recorded it, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say traffic was backed up and a work truck blocked the reduced-speed sign, so {D} could not see it. A photo of the truck blocking the sign is in evidence."),
        closings: ("The radar and dash camera recorded 80 mph through a marked work zone past a road crew, and with {PRIOR} behind {D.him}, {DL} knew what the cones mean, and what 80 miles an hour does to a crew standing beside the cones.", "A sign hidden by a work truck cannot warn any driver of a reduced limit, and traffic was backed up around {D}. The State must prove {D} knew the limit had been reduced and chose to speed past the crew."),
        timeline: [(0, "Morning: the work zone is set up."), (0, "10 a.m.: radar clocks {D}."), (0, "10:05 a.m.: the stop.")],
        identified: "A trooper's dash camera.",
        mood: .wantsConviction)

    static let parkingLotShootingBack = SmallCases.make(
        key: "story.followup.parkingLotShootingBack",
        category: .violent,
        headlines: ["Tow Driver Held at Gunpoint in Apartment Lot", "Driver From Shooting Case Charged With Pointing a Gun"],
        law: "assaultPointingGun",
        spec: "Pointed a gun at {V}, a tow truck driver, on {DATE}.",
        ages: 23...52,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} walked up to a tow truck hooking {D.his} car at an apartment complex and pointed a handgun at {V}. {V} stopped and called deputies. {DL} says {D.he} only showed the gun in a waistband holster.",
        state: [E(.video, 3, "Apartment Camera", "{D} points a handgun at the tow driver beside the truck."), E(.statement, 2, "Tow Driver's Call", "{V} tells dispatch a man is pointing a gun at the truck.")],
        defense: [E(.statement, 1, "Holstered Gun", "{DL} says the gun stayed in a holster.")],
        role: "Tow truck driver",
        exam: [.direct("What is your job?", "\"I'm a tow truck driver, and I repossess cars and remove vehicles parked illegally at apartment complexes.\""), .direct("What happened at the complex?", "\"I was hooking up a car with a towing chain when a man walked up to me, and pulled out a handgun.\""), .direct("What did {DL} do?", "\"{D.He} pointed the handgun at me and told me to stop, and to get away from {D.his} car.\""), .direct("What did you do?", "\"I stopped, raised my hands, backed away, and called dispatch, who called the sheriff's office.\""), .direct("What does the apartment camera show?", "\"{DL} walking up to the truck, pointing a handgun at me from about ten feet away, and holding it there.\""), .direct("What did {DL} say?", "\"{D.He} said the gun stayed in a waistband holster.\""), .cross("You were afraid for your life?", "\"Yes, very much, and I thought I would be shot.\""), .cross("You didn't hear a shot?", "\"No shot was fired, but I was sure I was about to be shot.\""), .cross("{DL}'s car was legally towed?", "\"It had been parked in a fire lane, with a warning sticker, according to the complex.\""), .cross("{DL} left after you backed away?", "\"Yes, {D.he} stayed by the car until the deputies came.\""), .cross("You called dispatch right away?", "\"Yes, I called dispatch from my cell phone, and the call is recorded.\"")],
        theory: ("{D} pointed a gun at a tow driver.", "A holstered gun shown in a dispute."),
        allocution: "\"The gun stayed at my hip in its holster, and I never pointed it at anyone. I was nervous that day, and I wanted to stop the tow. I know I was in this court before, and I should not have gone anywhere near that truck with it on me.\"",
        truths: ("{DL} had a prior case in this court and drew the gun after {V} refused to unhook the car.", "The camera angle hid {D.his} hand and a worker later said the gun never left the holster."),
        defendant: [.direct("Did you point a gun at the driver?", "\"No, I didn't. The gun stayed in my waistband holster, and I only showed it when I walked up.\""), .direct("Why did you show it?", "\"I was upset that he was towing my car, and I let him see it. I didn't point it.\""), .direct("What does the video show?", "\"It's hard to tell. It may look like I pointed it, but I only lifted my shirt.\""), .direct("Why did you walk up to him?", "\"I wanted him to stop towing. I was angry, and I didn't think.\""), .direct("What did you do when the deputies came?", "\"I told them what happened and handed over my gun.\""), .direct("What would you tell the tow driver?", "\"I'm sorry for frightening you. I shouldn't have shown the gun.\""), .cross("You have a record that affects whether you can carry a gun, don't you?", "\"I have a permit, and I've been told to be careful.\""), .cross("The video appears to show a gun pointed at him?", "\"It does, and I can't deny how it looks.\""), .cross("You showed a gun to a man doing his job?", "\"I did show a gun to a man doing his job, and I regret it.\""), .cross("You'll give up your gun?", "\"Yes, if the court says so, I'll give up my gun and my permit.\""), .cross("You'll apologize to the driver?", "\"Yes, I'll apologize to the driver in person, if he will allow it.\"")],
        openings: ("A tow truck driver who removes cars from apartment complexes was hooking up a car with a chain when a man walked up and pulled out a handgun, and {V} stopped and called deputies, and the handgun was pointed at {V}. {D} owned the car, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} only showed the gun in a waistband holster and never pointed it at anyone. A visible holster is a warning, not an assault."),
        closings: ("The tow driver says a man pulled out a handgun and pointed it, {V} stopped and called deputies, and after {PRIOR} {DL} knew exactly what that means to a driver.", "A gun in a holster at the waist is not a gun pointed at a person. The State must prove {D} pointed it at {V}."),
        timeline: [(0, "Morning: the tow truck arrives."), (0, "9 a.m.: {D} confronts the driver."), (0, "9:10 a.m.: deputies arrive.")],
        identified: "A tow driver's 911 call.",
        aggravating: ["The offense involved a weapon"],
        mood: .wantsConviction)

    static let rentalFireBack = SmallCases.make(
        key: "story.followup.rentalFireBack",
        category: .property,
        headlines: ["Landlord Flattens Neighbor's Shed With Skid Steer", "Landlord From Rental Fire Case Charged Over Demolished Shed"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly damaged the real property of {V}, a neighboring owner, by tearing down a shed, on {DATE}.",
        ages: 45...72,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} ran a skid steer through a storage shed on the line between {D.his} rental lot and {V}'s yard. {V} lost tools worth $1,100. {DL} says the shed sat on {D.his} land.",
        state: [E(.video, 3, "Yard Camera", "A skid steer pushes the shed over while {D} drives."), E(.document, 2, "Survey Plat", "The plat puts the shed inside {V}'s line.")],
        defense: [E(.statement, 1, "Old Fence Line", "{DL} says an old fence showed the line.")],
        role: "Neighbor",
        exam: [.direct("What is your property?", "\"A yard next to a lot that {DL} rents out, where I keep a shed with tools and equipment.\""), .direct("What happened to your shed?", "\"It was pushed over and crushed by a skid steer, and everything inside was ruined.\""), .direct("What was lost?", "\"About eleven hundred dollars in tools, and the shed itself, which I'd built years ago.\""), .direct("What does the yard camera show?", "\"A skid steer pushing the shed over, with {DL} at the controls, and then leaving the pieces in a heap.\""), .direct("What does the survey show?", "\"That the shed sat inside my property line, about four feet from the boundary.\""), .direct("What did {DL} say?", "\"{D.He} said the shed sat on {D.his} land and that an old fence showed the line.\""), .cross("There was an old fence?", "\"Yes, but it was falling down, and it didn't follow the survey line.\""), .cross("{DL} told you before?", "\"{D.He} said the shed was in the way, but never gave a notice.\""), .cross("{DL} could have gone to court?", "\"Yes, {D.he} could have gone to court, and I told {D.him} so.\""), .cross("The tools were destroyed?", "\"Most of them were crushed in the shed, and some were completely ruined.\""), .cross("{DL} offered to pay?", "\"Not at first, but later {D.he} offered to pay for the tools.\"")],
        theory: ("{D} flattened a shed on a neighbor's land.", "A landlord who believed the shed was on {D.his} property."),
        allocution: "\"I truly thought that shed sat on my own land, and the survey notice was buried in a stack of mail. I ran the skid steer believing I was clearing my property. I'm sorry to {V} for the tools, and I'll replace every one.\"",
        truths: ("{DL} had a prior case in this court and had received the survey plat a month earlier.", "The old fence line did run through the shed, and a prior owner had told {D} the shed was on that side."),
        defendant: [.direct("Did you tear down the shed?", "\"Yes, I did. I thought it was on my land, because of the old fence line.\""), .direct("Why did you think that?", "\"The old fence was there when I bought the lot, and I believed it marked the line.\""), .direct("Did you check the survey?", "\"No, I should have. I didn't want to pay for one, and I trusted the fence.\""), .direct("Did you know the tools were inside?", "\"No. I didn't look. I thought the shed was empty.\""), .direct("What did you do when the neighbor complained?", "\"I said I was sorry, and I offered to replace the tools.\""), .direct("What would you tell your neighbor?", "\"I'm sorry for destroying your shed. I'll pay for the shed and the tools.\""), .cross("You've been charged with damaging a neighbor's property before, haven't you?", "\"Yes, and I told the court I'd use the courts. I didn't.\""), .cross("You pushed down a building with a skid steer without a survey?", "\"I did, and I know how reckless it was.\""), .cross("The survey puts the shed on your neighbor's side?", "\"It does put the shed on his side, and I accept that now.\""), .cross("You'll pay eleven hundred dollars for the tools?", "\"Yes, I'll pay eleven hundred dollars for the tools, and for the shed too.\""), .cross("You'll hire a surveyor for any dispute?", "\"Yes, I'll hire a surveyor for any dispute from now on, before I touch anything.\"")],
        openings: ("{V} kept a shed with tools and equipment in a yard next to a lot that {D} rents out, and {D} ran a skid steer through the shed on the line between the properties, crushing everything inside, and {V} lost tools worth $1,100, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say the shed sat on {D}'s land, and an old fence showed the line. {D} believed {D.he} was clearing {D.his} own land."),
        closings: ("The shed was on the line between the lots, a skid steer pushed it over, and with {PRIOR} already on {D.his} record, {DL} knew exactly where the line ran and what stood on it.", "An old fence showed the line, and {D} believed the shed was on {D.his} land. The State must prove {D} knew it belonged to {V}."),
        timeline: [(-30, "The survey plat is mailed."), (0, "Afternoon: the shed comes down."), (1, "{DL} is charged.")],
        identified: "Yard camera footage.",
        mood: .divided)

    static let borrowedTruckBack = SmallCases.make(
        key: "story.followup.borrowedTruckBack",
        category: .property,
        headlines: ["Man Keeps Borrowed Log Splitter, Sells It Online", "Pickup Case Defendant Charged With Larceny Again"],
        law: "misdLarceny",
        spec: "Took and carried away a log splitter belonging to {V}, valued at $850, on {DATE}.",
        ages: 22...62,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} borrowed a log splitter from {V} for one weekend and sold it online for $500 two days later. {V} found it listed with {V.his} own engraved initials. {DL} says {V} told {D.him} to sell it to pay down a debt.",
        state: [E(.digital, 3, "Online Listing", "A listing with {D}'s phone number shows the splitter with engraved initials."), E(.statement, 2, "Buyer's Receipt", "A buyer's text says {D} sold it for $500.")],
        defense: [E(.statement, 1, "Debt Talk", "{DL} says {V} agreed it could be sold.")],
        role: "Property owner",
        exam: [.direct("What did you lend {DL}?", "\"A log splitter I bought a few years ago, which {DL} asked to borrow for one weekend to split firewood.\""), .direct("What happened?", "\"{DL} never returned it, and two days later I found it listed online for sale, with my own initials engraved on it.\""), .direct("What does the online listing show?", "\"A photo of my splitter, with the engraved initials, and {DL}'s phone number as the contact.\""), .direct("What did the buyer say?", "\"A text from the buyer said {DL} sold it for five hundred dollars.\""), .direct("What was the splitter worth?", "\"About eight hundred fifty dollars, and I used it every winter.\""), .direct("What did {DL} say?", "\"{D.He} said I told {D.him} to sell it to pay down a debt.\""), .cross("You and {DL} are friends?", "\"We've known each other for years, and I trusted {D.him} with the splitter.\""), .cross("{DL} owed you money?", "\"A small amount, for a past favor, nowhere near the value of the splitter.\""), .cross("You never said {DL} could sell it?", "\"Never. I only said {D.he} could borrow it for the weekend.\""), .cross("The buyer paid cash?", "\"Yes, according to the buyer's text, {D.he} was paid in cash at the pickup.\""), .cross("You got the splitter back?", "\"Yes, I got it back from the buyer, after the deputy called and explained.\"")],
        theory: ("{D} sold a splitter that was only borrowed.", "A sale made with the owner's blessing."),
        allocution: "\"{V} told me I could sell that log splitter to pay down a debt, and I took the permission as clear. I spent the money on rent. A voicemail was the only word I had from {V} afterward. I know I was in this court before, and I'll pay the five hundred dollars back.\"",
        truths: ("{DL} had a prior case in this court and deleted the listing after {V} called.", "{V} did say in a voicemail that {D} could 'get something for it' toward a debt."),
        defendant: [.direct("Did you sell the log splitter?", "\"Yes, I sold it. {V.He} told me I could sell it to cover what I owed {V.him}, so I did.\""), .direct("What did he say?", "\"{V.He} said, 'Just sell it, and we'll call it even,' when we talked about the money I owed.\""), .direct("Did you know he meant the splitter?", "\"I thought so. I took it as permission. I didn't think to ask again.\""), .direct("Why did you list it with your phone number?", "\"I wasn't hiding anything. I thought it was fine, and I used my own number.\""), .direct("What did you do when the deputy called?", "\"I told him what I understood, and I gave him the buyer's name.\""), .direct("What would you tell the owner?", "\"I'm sorry for the misunderstanding. I'll repay the five hundred dollars, and more.\""), .cross("You've been charged with selling borrowed property before, haven't you?", "\"Yes, and I told the court I'd always ask. I didn't ask this time.\""), .cross("You borrowed it for one weekend and sold it in two days?", "\"I did sell it two days after borrowing it, and I know how that looks.\""), .cross("He says he never agreed to a sale?", "\"That's what {V.he} says, and I understand why {V.he}'s upset.\""), .cross("You'll repay the owner?", "\"Yes, I'll repay the owner the full amount, with an apology.\""), .cross("You'll stay away from his property?", "\"Yes. I'll stay away from his property.\"")],
        openings: ("{V} lent a log splitter that {V.he} bought a few years ago to {D} for one weekend to split firewood, and {D} never returned it, and two days later {V} found it listed online for $500 with {V}'s own engraved initials on it, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say {V} told {D} to sell it to pay down a debt, and {D} sold it with the owner's blessing. {D} did not steal the splitter."),
        closings: ("The splitter was lent for one weekend, listed online two days later with {V}'s initials on it, and having faced {PRIOR} before, {DL} understood exactly whose it was, and what a log splitter with engraved initials is to its owner.", "A sale made with the owner's blessing is lawful, and {V} told {D} to sell it to pay down a debt. The State must prove {V} gave no such permission and that {D} knew the splitter was not {D.his} to sell."),
        timeline: [(-2, "{D} borrows the splitter."), (0, "The splitter is sold online."), (3, "{V} finds the listing.")],
        identified: "The online listing.",
        mood: .indifferent,
        genders: ["D": .male])

    static let parkingKnifeIntentBack = SmallCases.make(
        key: "story.followup.parkingKnifeIntentBack",
        category: .publicOrder,
        headlines: ["Dagger Found in Boot at Traffic Stop", "Nightclub Stabbing Defendant Charged With Concealed Weapon"],
        law: "concealedWeapon",
        spec: "Carried a concealed dagger about {D.his} person, off {D.his} own premises, on {DATE}.",
        ages: 21...50,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was stopped for a broken brake light. An officer found a six-inch dagger in {DL}'s boot. {DL} says it was a work knife left over from a fishing trip.",
        state: [E(.physical, 3, "Dagger", "A six-inch double-edged dagger in a sheath."), E(.video, 2, "Body Camera", "The officer pulls the dagger from {D}'s boot.", .search)],
        defense: [E(.statement, 1, "Fishing Knife", "{DL} says the knife was for gutting fish.")],
        role: "Patrol officer",
        exam: [.direct("What is your assignment?", "\"I'm a patrol officer, and I make traffic stops during the evening shift.\""), .direct("Why did you stop {DL}?", "\"A brake light was out on the car, and {D.he} was driving in a way that made me want to check on {D.him}.\""), .direct("What happened at the stop?", "\"I asked {D.him} to step out, and as {D.he} did, I noticed a bulge in {D.his} boot.\""), .direct("What did you find?", "\"A six-inch double-edged dagger in a sheath, inside {DL}'s boot, partly hidden by {D.his} pant leg.\""), .direct("What does your body camera show?", "\"Me pulling the dagger from {D.his} boot and holding it up, with {DL} watching.\""), .direct("What did {DL} say?", "\"{D.He} said it was a work knife left over from a fishing trip and used for gutting fish.\""), .cross("A fishing knife is common?", "\"Yes, but this one is double-edged and has a pointed tip.\""), .cross("{DL} didn't reach for it?", "\"No, {D.he} didn't reach for it, and kept {D.his} hands visible the whole time.\""), .cross("{DL} was polite?", "\"Yes, and {D.he} told me about it right away when I asked.\""), .cross("{DL} was on public property?", "\"Yes, it happened on a public road, and not on {D.his} own property.\""), .cross("No fish were in the car?", "\"No, there were no fish in the car, and no fishing gear in view.\"")],
        theory: ("{D} carried a hidden dagger.", "A fishing knife forgotten in a boot."),
        allocution: "\"I forgot that knife was in my boot after a fishing trip. I didn't realize it until the officer found it. It's a work knife I've used for years. I know I was in this court before, and I'm sorry for the trouble. I'll take it out of my boot for good.\"",
        truths: ("{DL} had a prior case in this court and had carried the dagger for months.", "{D} had worn the same boots on a fishing trip two days before, and the tackle bag held fresh scales."),
        defendant: [.direct("Did you carry the knife in your boot?", "\"Yes, I did. I had it from a fishing trip, and I forgot to take it out.\""), .direct("Why did you have a dagger?", "\"I used it to clean fish. It's a good knife, and I've had it for years.\""), .direct("Why was it in your boot?", "\"I put it there when I walked back from the lake, and I never took it out.\""), .direct("Did you plan to use it on anyone?", "\"No. I've never used it on anyone, and I never would.\""), .direct("What did you do when the officer asked?", "\"I told {OFF.him} it was in my boot and showed it to {OFF.him}.\""), .direct("What would you tell the officer?", "\"I'm sorry for carrying it. I should have left it in my tackle box.\""), .cross("You've been charged with carrying a concealed weapon before, haven't you?", "\"Yes, and after that case I told the court I'd turned a corner. I forgot.\""), .cross("A six-inch dagger isn't a fishing tool, is it?", "\"I used it for fish, but I know it's a dagger.\""), .cross("You knew it was in your boot while you drove?", "\"I'd put it there that morning, but I had forgotten it was there by the time I drove.\""), .cross("You'll give up the knife?", "\"Yes, I'll give up the knife today and hand it to the deputy.\""), .cross("You'll leave knives at home?", "\"Yes. I'll leave my knives at home.\"")],
        openings: ("A patrol officer on the evening shift stopped {D} for a broken brake light and, after seeing {D} drive in a way that made the officer want to check, found a six-inch dagger in {D}'s boot, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say it was a work knife left over from a fishing trip, used to gut fish. {D} forgot it was in the boot."),
        closings: ("A six-inch dagger was in {D}'s boot at a traffic stop, and since {PRIOR}, {DL} could not have missed what carrying a concealed blade means.", "A fishing knife forgotten in a boot is not a concealed weapon by intent. The State must prove {D} knew it was there and meant to conceal it."),
        timeline: [(-2, "{D} goes fishing."), (0, "Night: the brake-light stop."), (0, "Night: the dagger is found.")],
        identified: "A traffic stop.",
        aggravating: ["The offense involved a weapon"],
        mood: .divided)

