        exam: [.direct("What is your role?", "\"I'm the account holder whose name appeared on a check cashed at the credit union.\""), .direct("What happened?", "\"A check for thirty-eight hundred dollars was cashed from my account, and I never wrote it.\""), .direct("How did you find out?", "\"The credit union called me, and later I saw the check image, which had a signature that wasn't mine.\""), .direct("What does the forged check show?", "\"A signature that doesn't match the signature card on file, and a payee line with {DL}'s name.\""), .direct("What does the teller camera show?", "\"{DL} handing the check across the counter and receiving cash.\""), .direct("What did {DL} say?", "\"{D.He} said I wrote the check for work {D.he} did, a deck repair.\""), .cross("{DL} did work for you?", "\"{D.He} gave me an estimate once, but I never hired {D.him}.\""), .cross("You didn't promise thirty-eight hundred dollars?", "\"Never. I didn't agree to any price, and I never wrote {D.him} a check.\""), .cross("{DL} knows you?", "\"Yes, I know {D.him} from the neighborhood, and we've spoken before.\""), .cross("{DL} gave you a bill?", "\"No, {D.he} never gave me a bill, and never sent an invoice.\""), .cross("You reported it right away?", "\"Yes, I reported it the same day, as soon as the credit union called me.\"")],
