    static let hotCarDeathBack = SmallCases.make(
        key: "story.followup.hotCarDeathBack",
        category: .cyber,
        headlines: ["Ex-Employee Logs Into Company Code Server Using Old Password", "Developer From Earlier Case Charged With Computer Access"],
