        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} logged into {V}'s code server six times using a password from a former job and copied project files. {V}'s logs show the sessions. {DL} says {DL} only wanted personal notes left on the server.",
        state: [E(.digital, 3, "Server Logs", "Six logins from {D}'s home connection using a retired password."), E(.digital, 2, "Copied Files", "Project folders copied to {D}'s laptop.", .search)],
        defense: [E(.statement, 1, "Personal Notes", "{DL} says {D.he} wanted old notes only.")],
        role: "Company owner",
        exam: [.direct("What is your business?", "\"I own a small software company, and {DL} worked for me as a developer until about a year ago.\""), .direct("What did you discover?", "\"Six logins to our code server from an outside connection, using a retired password from {DL}'s time at the company.\""), .direct("What do the server logs show?", "\"Six sessions, each lasting several minutes, from {DL}'s home connection, at odd hours of the night.\""), .direct("What was copied?", "\"Project folders, including source code for a product we're developing, copied to a laptop.\""), .direct("How do you know it was {DL}?", "\"The connection came from {D.his} home address, and the laptop was seized with the copied files on it.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} only wanted personal notes {D.he} left on the server.\""), .cross("The password should have been disabled?", "\"Yes, the password should have been disabled, but it was missed when {D.he} left the company.\""), .cross("{DL} didn't change anything?", "\"No, {D.he} didn't change or delete anything, only copied the project folders.\""), .cross("{DL} signed a confidentiality agreement?", "\"Yes, I'll delete every copy in front of the deputy, and sign a statement saying so.\""), .cross("The project is valuable?", "\"Yes, the project is valuable, and it represents many months of work by our team.\""), .cross("{DL} didn't give the files to a competitor?", "\"Not that we know of, though we're still checking whether the files went anywhere.\"")],
        theory: ("{D} entered a former employer's server without authority.", "A former worker who wanted personal notes."),
        allocution: "\"I logged in only to get my own notes, and I thought I still had the right. I'm sorry to {V}, whose server I used six times. I'll hand over every file I copied and stay away from that account.\"",
        truths: ("{DL} had a prior case in this court and copied client project files along with the notes.", "The password was never disabled, and {D} copied only a folder labelled with {D.his} own name."),
        defendant: [.direct("Did you access your former employer's server?", "\"I did, six times. I wanted to retrieve personal notes I left there when I quit.\""), .direct("Why did you copy project folders?", "\"The notes were mixed in with the project folders, and copying everything was easier.\""), .direct("Did you know it wasn't allowed?", "\"I knew I wasn't supposed to access it. I thought the password still worked, so I tried.\""), .direct("Did you give the files to anyone?", "\"No. They're on my laptop, and I haven't used them.\""), .direct("What did you do when your former boss called?", "\"I told him I'd delete them and offered to give back my laptop.\""), .direct("What would you tell your former employer?", "\"I'm sorry for accessing your server without permission. I'll delete everything.\""), .cross("You've been charged with unauthorized computer access before, haven't you?", "\"Yes, and I stood in this courtroom and said that I had learned my lesson. I'm ashamed.\""), .cross("You logged in six times from your home at night?", "\"I did log in six times at night from home, and I know how that looks.\""), .cross("You copied project source code?", "\"I did copy the source code, and I shouldn't have done that.\""), .cross("You'll surrender your laptop?", "\"Yes, I'll surrender my laptop to the deputies, so they can see exactly which files are on it.\""), .cross("You'll delete the files in front of the deputy?", "\"Yes, I'll delete every copy in front of the deputy, and sign a statement saying that I did.\"")],
        openings: ("{D} logged into {V}'s code server six times using a password from a former job and copied project files, and {V}'s logs show the sessions, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say {D} only wanted personal notes left on the server from the old job, and had no interest in the project files. {D} meant to retrieve what was {D.his}."),
