        state: [E(.digital, 3, "Payment Records", "Payments from {D}'s account to a traffic-flooding service."), E(.digital, 2, "Server Logs", "Traffic spikes line up with the commands sent from {D}'s account.")],
        defense: [E(.statement, 1, "Just a Test", "{DL} says {D.he} only tested the service on a friend's server.")],
        role: "Tournament organizer",
        exam: [.direct("What is your role?", "\"I organize an esports tournament, with teams from around the region and sponsors who pay for the event.\""), .direct("What happened at the final?", "\"Our servers were flooded with traffic during the final match and went offline, ending the stream and the match.\""), .direct("What was the loss?", "\"Seventy-five hundred dollars in sponsor fees, which the sponsors withheld after the crash.\""), .direct("What do the payment records show?", "\"Payments from {DL}'s account to a service that sells traffic-flooding attacks.\""), .direct("What do the server logs show?", "\"Traffic spikes at the exact moments that commands were sent from {DL}'s account to that service.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} only tested the service on a friend's server, and that it got out of control.\""), .cross("{DL} played in the tournament?", "\"Yes, {D.he} played in the tournament, and {D.his} team was eliminated before the final.\""), .cross("{DL} knew the final was starting?", "\"Yes, {D.he} knew the final was starting, since {D.he} had been watching the stream.\""), .cross("{DL} didn't take credit?", "\"No, {D.he} didn't take credit for it, and {D.he} denied it at first.\""), .cross("The attack lasted twenty minutes?", "\"About twenty minutes, and it ruined the match for everyone watching.\""), .cross("A friend's server could have been the target?", "\"The logs show that the traffic was aimed at our servers, and not at anyone else's.\"")],
        theory: ("{D} knocked a tournament offline.", "A test that went wrong."),
