        state: [E(.video, 3, "Gate Camera", "{D} stands in front of the gate and waves off deputies."), E(.statement, 2, "Deputy Report", "Deputies say they asked {D} five times to open the gate.")],
        defense: [E(.statement, 1, "Checking IDs", "{DL} says {D.he} was following a neighborhood rule.")],
        role: "Sheriff's deputy",
        exam: [.direct("What is your assignment?", "\"I'm a sheriff's deputy, and I was responding to a noise complaint in a gated subdivision.\""), .direct("What happened at the gate?", "\"A man stood in front of the gate and wouldn't let my patrol car pass, waving us off and demanding identification.\""), .direct("What does the gate camera show?", "\"{DL} standing in front of the gate with arms out, refusing to move, while my car waited with lights on.\""), .direct("How long did it last?", "\"Twelve minutes, while a noise complaint went unanswered inside the subdivision.\""), .direct("What did you do?", "\"I asked {DL} five times to open the gate, explaining that we were responding to a call.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} was following a neighborhood rule, and checking IDs.\""), .cross("The subdivision has a rule?", "\"Yes, the neighborhood has a rule that the gates stay closed unless an ID is checked.\""), .cross("The rule doesn't apply to deputies?", "\"No, the rule doesn't apply to deputies, who are allowed through when responding to calls.\""), .cross("{DL} is a volunteer?", "\"Yes, {D.he} volunteers as a gate guard with the neighborhood association, on weekends.\""), .cross("{DL} eventually moved?", "\"Yes, {D.he} moved only after a supervisor arrived and explained the law.\""), .cross("The noise complaint was minor?", "\"Yes, it was a minor noise call, but it was still a call that we had to answer.\"")],
        theory: ("{D} blocked deputies from responding.", "A resident following a gate rule."),
        allocution: "\"I only stopped the cars to check IDs because the rule says everyone checks in. I did it five times that week. I'm sorry that deputies were held up for twelve minutes, and I'll never block the gate again.\"",
        truths: ("{DL} had a prior case in this court and said, 'you are not coming in.'", "The neighborhood posted a sign telling all visitors to check in, and a board member had told {D} that applied to everyone."),
        defendant: [.direct("Did you block the deputies?", "\"I stood at the gate and asked for identification, as our rule says. I didn't think I was blocking anything.\""), .direct("What is the rule?", "\"No one enters without an ID check, and I volunteer as a gate guard. I was following it.\""), .direct("Did you know deputies are exempt?", "\"I thought they were supposed to stop like everyone else. No one told me otherwise.\""), .direct("Why did you refuse five times?", "\"I was nervous and wanted to do the right thing. I wasn't trying to defy anyone.\""), .direct("What did you do when the supervisor arrived?", "\"When the supervisor arrived, I opened the gate right away and I apologized to everyone.\""), .direct("What would you tell the deputies?", "\"I'm sorry for the delay. I didn't understand the rule, and I'll learn it.\""), .cross("You've been warned about gate rules before, haven't you?", "\"Yes, and I told the association I'd learn them. I didn't learn them well enough.\""), .cross("Twelve minutes is a long time for a deputy to wait?", "\"It is a long time for deputies to wait, and I regret it.\""), .cross("A noise call is still a call?", "\"A noise call is still a call, and I know that now.\""), .cross("You'll step down as a gate guard?", "\"Yes, I'll step down as a gate guard if the association asks me to.\""), .cross("You'll take training from the association?", "\"Yes. I'll take the training from the association.\"")],
        openings: ("{D} stood in front of a subdivision gate and refused to let deputies pass for twelve minutes while they responded to a noise call. {DL} came before this court in {PRIORDATE} over {PRIOR}, and the gate camera is in evidence.", "The defense will say {D} was only checking IDs, as the neighborhood rules require of anyone coming through the gate. {D} meant to follow the rules, not to block deputies."),
